window.S17Page={"sceneId":"co2","caseId":"s17x-co2-completion-zone-design","name":"射孔参数智能设计","title":"射孔参数智能设计","summary":"本例关注完井选层组合：调预算、含水上限和层间隔离条件，查看每个组合为何留下或被排除。","directory":"expansion-cases","caseVersion":"1.2.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){'use strict';
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));const sum=a=>a.reduce((s,x)=>s+x,0),mean=a=>a.length?sum(a)/a.length:0;
function rng(seed){let s=seed>>>0;return ()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296}}
function solve(A,b){A=A.map((r,i)=>r.slice().concat(b[i]));const n=b.length;for(let j=0;j<n;j++){let p=j;for(let i=j+1;i<n;i++)if(Math.abs(A[i][j])>Math.abs(A[p][j]))p=i;[A[j],A[p]]=[A[p],A[j]];if(Math.abs(A[j][j])<1e-12)throw Error('训练矩阵退化');let v=A[j][j];for(let k=j;k<=n;k++)A[j][k]/=v;for(let i=0;i<n;i++)if(i!==j){v=A[i][j];for(let k=j;k<=n;k++)A[i][k]-=v*A[j][k]}}return A.map(r=>r[n])}
function ridge(rows,features,outputs){const raw=rows.map(d=>features(d.x)),d=raw[0].length,mu=Array.from({length:d},(_,j)=>mean(raw.map(r=>r[j]))),sd=mu.map((m,j)=>Math.max(1e-8,Math.sqrt(mean(raw.map(r=>(r[j]-m)**2)))));const scale=x=>[1,...features(x).map((v,j)=>(v-mu[j])/sd[j])],X=rows.map(r=>scale(r.x)),A=Array.from({length:d+1},(_,j)=>Array.from({length:d+1},(_,k)=>sum(X.map(r=>r[j]*r[k]))+(j===k&&j>0?.01:0)));const coef=Array.from({length:outputs},(_,o)=>solve(A,Array.from({length:d+1},(_,j)=>sum(rows.map((r,i)=>X[i][j]*r.y[o])))));return {predict:x=>{const z=scale(x);return coef.map(c=>sum(c.map((v,j)=>v*z[j])))},coef,mu,sd}}
function batch(n,seed,make){const r=rng(seed);return Array.from({length:n},(_,i)=>make(r,i))}function mae(pred,truth){return mean(pred.map((p,i)=>Math.abs(p-truth[i])))}
const panel=(title,body)=>'<article class="panel"><h2>'+title+'</h2>'+body+'</article>';const plot=(title,body,desc='')=>'<article class="panel chart"><h2>'+title+'</h2>'+body+'<p class="small">'+desc+'</p></article>';

const layers=[{id:'A',depth:2400,p:25,liquid:55,water:.15,banned:false},{id:'B',depth:2430,p:30,liquid:85,water:.65,banned:false},{id:'C',depth:2460,p:24,liquid:43,water:.1,banned:false},{id:'D',depth:2490,p:28,liquid:90,water:.98,banned:true}];
function assess(actions,p){const active=layers.filter((_,i)=>actions[i]>0),cost=sum(actions.map(a=>a===2?18:a===1?10:0)),rates=layers.map((l,i)=>{const q=actions[i]===2?l.liquid*1.35:actions[i]===1?l.liquid:0;return {id:l.id,liquid:q,oil:q*(1-l.water),water:q*l.water}}),oil=sum(rates.map(d=>d.oil)),water=sum(rates.map(d=>d.water)),liquid=oil+water,reasons=[];if(!active.length)reasons.push('未连通目标层');if(layers.some((l,i)=>l.banned&&actions[i]))reasons.push('D 为禁射水层');if(cost>p.budget)reasons.push('资源超预算');if(liquid&&water/liquid>p.waterLimit+1e-9)reasons.push('总含水率超限');if(!p.isolation&&active.length>1&&Math.max(...active.map(d=>d.p))-Math.min(...active.map(d=>d.p))>4)reasons.push('无分层隔离且层间压差 > 4 MPa');return {actions:actions.slice(),cost,rates,oil,water,liquid,watercut:liquid?water/liquid:0,utility:oil-.45*water,reasons}}function run(p={}){p=Object.assign({"budget": 42, "waterLimit": 0.4, "isolation": 1},p);let points=[];for(let a=0;a<3;a++)for(let b=0;b<3;b++)for(let c=0;c<3;c++)for(let d=0;d<3;d++)points.push(assess([a,b,c,d],p));const feasible=points.filter(d=>!d.reasons.length).sort((a,b)=>b.utility-a.utility||a.cost-b.cost),reasons={};points.forEach(d=>d.reasons.forEach(s=>reasons[s]=(reasons[s]||0)+1));return {params:p,points,best:feasible[0]||null,top:feasible.slice(0,10),baseline:assess([1,1,1,0],p),layers,metrics:{candidates:81,feasible:feasible.length,violations:0,exhaustiveCoverage:1},rejectionCounts:reasons,summary:feasible.length?'81 个组合完整搜索，'+feasible.length+' 个可行；推荐 '+feasible[0].actions.map((a,i)=>layers[i].id+['不射','低密','高密'][a]).join(' / ')+'。':'当前约束下无可行组合；请检查预算、含水上限与隔离条件。',data:{kind:'教学层段属性，固定完整枚举，不训练网络',units:{rate:'m³/d',pressure:'MPa',budget:'教学资源指数'}}}}
function describe(d){return d.actions.map((a,i)=>layers[i].id+['不射','低密','高密'][a]).join(' / ')+'；油 '+d.oil.toFixed(1)+'、水 '+d.water.toFixed(1)+' m³/d；'+(d.reasons.join('；')||'全部约束满足')}
function render(r,h){const {n,svg,axes,circle,metric,table}=h;let sc=axes('资源消耗 / 教学指数','目标：油 − 0.45×水 / m³/d',[0,72],[-50,170]);sc+=r.points.map((d,i)=>circle(58+d.cost/72*497,258-(d.utility+50)/220*236,4,d.reasons.length?'#cdd8d1':'#267d78','class="pick" data-pick="'+i+'"')).join('');if(r.best)sc+=circle(58+r.best.cost/72*497,258-(r.best.utility+50)/220*236,8,'none','stroke="#173b43" stroke-width="2"');let zon='';r.layers.forEach((l,i)=>{const a=r.best?r.best.actions[i]:0;zon+='<rect x="65" y="'+(30+i*58)+'" width="260" height="42" fill="'+(l.banned?'#c5d8e3':'#e1cfac')+'"/><text x="78" y="'+(57+i*58)+'">'+l.id+' · '+l.depth+' m · '+l.p+' MPa</text><rect x="340" y="'+(30+i*58)+'" width="20" height="42" fill="#78959e"/><path d="M360 '+(51+i*58)+'h'+(a?70:0)+'" stroke="'+(a?'#267d78':'#bdc9c4')+'" stroke-width="'+(a===2?8:4)+'"/><text x="450" y="'+(57+i*58)+'">'+['不射','低孔密','高孔密'][a]+'</text>'});return '<div class="metric-grid">'+metric('可行组合',r.metrics.feasible,'/81 个完整候选')+metric('推荐产油',r.best?n(r.best.oil,1):'无方案','m³/d')+metric('推荐含水率',r.best?n(r.best.watercut*100,1):'—','% · 流量加权')+metric('推荐违规',0,'条约束')+'</div><div class="charts">'+plot('当前选层与连通状态',svg(zon),'右侧连线表示射开，粗线表示高孔密；D 水层始终禁射。图示关注层段组合，不代表孔眼实际尺寸。')+plot('所有组合都展示，排除理由可追溯',svg(sc),'绿色点为可行组合，灰点被约束排除；深色圆环表示推荐组合；点击任何组合，读取它的油水贡献和排除原因。')+'</div>'+panel('四层输入与动作假设',table(['层','深度 / m','压力 / MPa','低孔密产液 / m³/d','含水率','限制'],r.layers.map(l=>[l.id,l.depth,l.p,l.liquid,n(l.water*100,0)+'%',l.banned?'禁射':'可选']))+'<p class="small">低孔密消耗 10 资源，高孔密消耗 18，产液量为低孔密的 1.35 倍；不射的流量和资源均为 0。两档是教学动作等级，未指定实际孔/米，不代表现场孔密方案。总含水率 = 各层产水之和 / 各层产液之和。</p>')+panel('选中组合','<p id="selection">'+(r.best?describe(r.best):'无可行方案')+'</p>')+panel('排名靠前的可行组合',table(['A / B / C / D','资源','油 / m³/d','水 / m³/d','含水率'],r.top.map(d=>[d.actions.map(a=>['—','低','高'][a]).join(' / '),d.cost,n(d.oil,1),n(d.water,1),n(d.watercut*100,1)+'%'])))+panel('统一低孔密基线与约束解释','<p>'+describe(r.baseline)+'</p>'+table(['排除原因（可重复计数）','涉及组合数'],Object.entries(r.rejectionCounts))) }
g.CaseEngine={run,render,describe,assess,layers};})(globalThis);

